(()=>{document.documentElement.classList.add('master-ready');const load=(u)=>fetch(u).then(r=>r.ok?r.json():null).catch(()=>null);Promise.all([load('../data/site.json'),load('../data/theme.json'),load('../data/modules.json')]).then(([site,theme,modules])=>{window.MasterData={site,theme,modules};document.dispatchEvent(new CustomEvent('master:ready',{detail:window.MasterData}))})})();